{
  "scenario_id": "sc-11135c",
  "overall_assessment": "anomalies",
  "findings": [
    {
      "benefit": "IP",
      "years": null,
      "pattern": "recovery",
      "direction": "decrease",
      "magnitude": "pooled termination A/E 0.389 (z=-22.1), i.e. actual CV recoveries ~61% below the assumed rate; expected recoveries 1302 (large cell, not noise)",
      "confidence": 0.95,
      "evidence": [
        "artifacts/ae_ip_termination.csv: Cardiovascular A/E=0.389 vs all other diagnoses ~1.0 (Cancer 0.999, Injury 0.974, Mental Health 1.005, Musculoskeletal 1.017, Other 0.983)",
        "summary.json: IP overall_termination_ae=0.9403 — the whole-book recovery shortfall is driven almost entirely by the single CV cell",
        "CV cell carries expected recoveries=1302 (one of the larger diagnosis pools), so the -22.1 z is real, not a small-cell artefact"
      ],
      "recommended_action": "Investigate cardiovascular IP termination/recovery experience before any assumption sign-off: (1) pull claim-level CV cases and reconcile terminations by onset year, duration and outcome code to rule out misclassification/re-labelling of CV claims or administrative coding change; (2) compare observed CV recovery/termination curve vs the assumed curve to see whether the assumed CV recovery rate is too optimistic or whether CV cases are persisting on claim longer than modelled; (3) if the shortfall is genuine and structural, revise the CV recovery-rate assumption in pricing and valuation (it is the main driver pulling overall IP termination A/E to 0.94). No other line shows a material anomaly: Death, CI and TPD yearly A/E sit within Poisson/noise bands (Death 2016 z+2.8 is a single reversion year, below the 4.5 threshold; TPD 2016-18 and IP 2015-16 ~+0.03 blips revert and are within each line's own scatter), so those are left out."
    }
  ]
}

